\caption{MLGD outer loop (black-box loss)} \raggedright
\textbf{Input:} Pretrained score network $s_\theta$ for $\mathcal{P}(X)$;
black-box loss $\mathcal{L}: \mathcal{X} \to \mathbb{R}$;
noise schedule $\{\bar{\alpha}_t\}_{t=1}^T$;
guidance strengths $\{\zeta_t\}_{t=1}^T$.\\
\textbf{Output:} Sample $x_0$ guided toward $\mathcal{G}$.\\[3pt]
\begin{algorithmic}[1]
\State $x_T \sim \mathcal{N}(0, I)$
\For{$t = T, T{-}1, \ldots, 1$}
  \State $\hat{x}_0 \leftarrow \tfrac{1}{\sqrt{\bar{\alpha}_t}}\bigl(x_t + (1-\bar{\alpha}_t)\,s_\theta(x_t,t)\bigr)$
    \Comment{Tweedie estimate}
  \State $x_{t-1} \leftarrow \textsc{DDIM\_step}(x_t, s_\theta, t)\;-\;\zeta_t\,\nabla_{x_t}\mathcal{L}(\hat{x}_0)$
    \Comment{Denoising step $-$ inner-estimator guidance (Alg.~\ref{alg:inner-estimator})}
\EndFor
\State \Return $x_0$
\end{algorithmic}

\For{$t = T, T{-}1, \ldots, 1$}
  \State $\hat{x}_0 \leftarrow \tfrac{1}{\sqrt{\bar{\alpha}_t}}\bigl(x_t + (1-\bar{\alpha}_t)\,s_\theta(x_t,t)\bigr)$
    \Comment{Tweedie estimate}
  \State $x_{t-1} \leftarrow \textsc{DDIM\_step}(x_t, s_\theta, t)\;-\;\zeta_t\,\nabla_{x_t}\mathcal{L}(\hat{x}_0)$
    \Comment{Denoising step $-$ inner-estimator guidance (Alg.~\ref{alg:inner-estimator})}

\caption{Inner estimator for $\mathcal{L}(x)$ (our contribution)} \raggedright
\textbf{Input:} Query conditioning $x$; pretrained differentiable sampler $f_\phi$ for $\mathcal{P}(Y{\mid}X)$;
target sample $\mathcal{S}_{\mathcal{G}} \sim \mathcal{G}$; number of conditional samples $n_{\mathrm{cond}}$; distributional distance $\mathcal{L}$ (e.g.\ MMD, SWD).\\
\textbf{Output:} Estimate $\widehat{\mathcal{L}}(x)$ and its gradient $\nabla_x \widehat{\mathcal{L}}(x)$.\\[3pt]
\begin{algorithmic}[1]
\State Sample internal noise $\eta_1, \ldots, \eta_{n_{\mathrm{cond}}} \stackrel{\text{iid}}{\sim} \pi$
\State $\mathcal{S}_{\mathrm{cond}} \leftarrow \{f_\phi(x, \eta_i)\}_{i=1}^{n_{\mathrm{cond}}}$
  \Comment{Fast conditional samples; differentiable in $x$}
\State $\widehat{\mathcal{L}}(x) \leftarrow \mathcal{L}\bigl(\mathcal{S}_{\mathrm{cond}},\, \mathcal{S}_{\mathcal{G}}\bigr)$
  \Comment{Plug-in distributional-loss estimator}
\State $\nabla_x \widehat{\mathcal{L}}(x) \leftarrow \textsc{autograd}(\widehat{\mathcal{L}}(x),\, x)$
  \Comment{Backprop through $f_\phi$}
\State \Return $\widehat{\mathcal{L}}(x),\; \nabla_x \widehat{\mathcal{L}}(x)$
\end{algorithmic}

The kernel $k$ is the multi-bandwidth RBF
\begin{equation}
k(a,b) = \sum_{\ell=1}^{5} \exp\!\Bigl(-\frac{\|a-b\|^2}{\sigma \cdot 2^{\ell-3}}\Bigr), \end{equation}
where $\sigma$ is the mean pairwise squared distance of the merged
sample.

For two probability distributions $P$ and $Q$ on $\mathbb{R}^d$, the 1-Wasserstein distance $W_1$ is defined as:
\begin{equation}
W_1(P, Q) = \inf_{\gamma \in \Gamma(P, Q)} \mathbb{E}_{(x,y) \sim \gamma}[\|x - y\|_1]
\end{equation}
where $\Gamma(P, Q)$ denotes the set of all joint distributions with marginals $P$ and $Q$.

For one-dimensional distributions $P$ and $Q$ on $\mathbb{R}$, the 1-Wasserstein distance has a closed-form expression in terms of the cumulative distribution functions (CDFs):
\begin{equation}
W_1(P, Q) = \int_{-\infty}^{\infty} |F_P(x) - F_Q(x)| \, dx
\end{equation}
where $F_P$ and $F_Q$ are the CDFs of $P$ and $Q$, respectively.

Given samples $S_1 = \{s_1, \ldots, s_m\}$ from $P$ and $S_2 = \{t_1, \ldots, t_n\}$ from $Q$ (assuming $m = n$ for simplicity), let $s_{(1)} \leq s_{(2)} \leq \cdots \leq s_{(m)}$ and $t_{(1)} \leq t_{(2)} \leq \cdots \leq t_{(n)}$ denote the sorted samples. The 1-Wasserstein distance can be estimated as:
\begin{equation}
W_1(S_1, S_2) = \frac{1}{m} \sum_{i=1}^{m} |s_{(i)} - t_{(i)}|.
\end{equation}

The SWD between distributions $P$ and $Q$ is defined as:
\begin{equation}
\text{SWD}(P, Q) = \int_{\mathbb{S}^{d-1}} W_1(\pi_\theta \# P, \pi_\theta \# Q) \, d\theta
\end{equation}
where $\mathbb{S}^{d-1}$ is the unit sphere in $\mathbb{R}^d$, $\pi_\theta$ denotes projection onto direction $\theta$, $\pi_\theta \# P$ and $\pi_\theta \# Q$ are the distributions of the projected points along that direction, and $W_1$ is the 1-Wasserstein distance.

In practice, we approximate this integral by averaging the Wasserstein distance over $L$ random one-dimensional projections:
\begin{equation}
\text{SWD}(P, Q) \approx \frac{1}{L} \sum_{\ell=1}^{L} W_1(\pi_{\theta_\ell} \# P, \pi_{\theta_\ell} \# Q)
\end{equation}
where $\theta_1, \ldots, \theta_L$ are uniformly sampled from $\mathbb{S}^{d-1}$.

\caption{MLGD-F{} Conditional Sampling (full detailed version)} \footnotesize
\raggedright
\textbf{Input:}
Pretrained score network $s_\theta$ for $\mathcal{P}(X)$;
pretrained few-step model $f_\phi$ for $\mathcal{P}(Y|X)$;
target distribution $\mathcal{G}$;
drift function $f(x,t)$;
diffusion coefficient $g(t)$;
noise schedule $\{\bar{\alpha}_t\}_{t=1}^T$;
step-size schedule $\{\zeta_t\}$ (e.g.\ $\zeta_t = \zeta' / \|\nabla \mathcal{L}\|$
as in~\citep{DiffusionPosteriorSampling}, with $\zeta'$ proportional to $\beta$).\\
\textbf{Parameters:}
Total timesteps $T$;
step size $\Delta t = 1/T$;
inverse temperature $\beta \ge 0$ (target is
$\mathcal{Q}_\beta(x) \propto \mathcal{P}(x)\, e^{-\beta\mathcal{L}(x)}$;
$\beta=0$ samples from $\mathcal{P}$, $\beta\to\infty$ concentrates at
$\arg\min_x \mathcal{L}$);
MC samples $n_{\text{MC}}$ (number of perturbed $\hat{x}_0$ estimates used to stabilize the gradient);
conditional samples $n_{\text{cond}}$ (samples drawn from $\mathcal{P}(Y|X)$ per candidate);
target samples $n_{\text{target}}$ (samples drawn from $\mathcal{G}$);
distributional loss $\mathcal{L}$ (e.g.\ MMD, SWD).\\
\textbf{Output:} Sample $x_0$ approximately drawn from $\mathcal{Q}_\beta$\\[4pt]
\begin{algorithmic}[1]
\State $S_{\mathcal{G}} \leftarrow \{\tilde y_1, \ldots, \tilde y_{n_{\text{target}}}\} \sim \mathcal{G}$
  \Comment{Sample target distribution once}
\State $x_T \sim \mathcal{N}(0, I)$
\For{$i = 0, \ldots, T-1$}
  \State $t \leftarrow 1 - i \cdot \Delta t$
  \State $\hat{x}_0 \leftarrow \tfrac{1}{\sqrt{\bar{\alpha}_t}}
    \bigl(x_t + (1-\bar{\alpha}_t)\,s_\theta(x_t,t)\bigr)$
    \Comment{Tweedie estimate of $x_0$}
  \State $\{\hat{x}_0^{(i)}\}_{i=1}^{n_{\text{MC}}} \sim
    \mathcal{N}\!\left(\hat{x}_0,\; \tfrac{g(t)}{\sqrt{1+g(t)^2}}\,I\right)$
    \Comment{MC perturbations around $\hat{x}_0$}
  \For{$i = 1, \ldots, n_{\text{MC}}$}
    \State $S_{Y|X}^{(i)} \leftarrow \{y_1^{(i)}, \ldots, y_{n_{\text{cond}}}^{(i)}\}
      \sim \mathcal{P}(Y \mid X{=}\hat{x}_0^{(i)})$ \textbf{using} $f_\phi$
      \Comment{Fast conditional samples}
    \State $\mathcal{L}^{(i)} \leftarrow \mathcal{L}(S_{Y|X}^{(i)},\, S_{\mathcal{G}})$
      \Comment{Distributional loss against target}
  \EndFor
  \State $\nabla_{x_t}\mathcal{L} \leftarrow -\nabla_{x_t}
    \log\!\left(\tfrac{1}{n_{\text{MC}}}\sum_{i=1}^{n_{\text{MC}}}
    \exp\!\left(-\mathcal{L}^{(i)}\right)\right)$
    \State $\Delta x_t \leftarrow -\bigl[f(x_t,t) - g(t)^2\,s_\theta(x_t,t)\bigr]\Delta t
    + g(t)\sqrt{\Delta t}\,\epsilon$
    \Comment{Standard denoising step}
  \State $x_{t-1} \leftarrow x_t + \Delta x_t - \zeta_t\,\nabla_{x_t}\mathcal{L}$
    \Comment{Denoising + guidance}
\EndFor
\State \Return $x_0$
\end{algorithmic}

