\bigl|\widehat{\mathcal{L}}_\phi(x) - \mathcal{L}(x)\bigr|
    \;\le\;
    \underbrace{\bigl|\widehat{\mathcal{L}}_\phi(x)
                     - \mathcal{L}_\phi(x)\bigr|}_{T_1\ \text{(Monte Carlo)}}
    \;+\;
    \underbrace{\bigl|\mathcal{L}_\phi(x) - \mathcal{L}(x)\bigr|}_{T_2\ \text{(distillation)}},

|T_1| \;\le\;
    K_{\max}\sqrt{8\,\log(2/\delta)\,(1/n + 1/m)}
    \;\le\;
    2\sqrt{2}\,K_{\max}\!\left(\sqrt{\tfrac{\log(2/\delta)}{n}}
                              + \sqrt{\tfrac{\log(2/\delta)}{m}}\right),

Write $n := n_{\mathrm{cond}}$ and $m := n_{\mathrm{target}}$. By the
triangle inequality,
\begin{equation}
  \bigl|\widehat{\mathcal{L}}_\phi(x) - \mathcal{L}(x)\bigr|
    \;\le\;
    \underbrace{\bigl|\widehat{\mathcal{L}}_\phi(x)
                     - \mathcal{L}_\phi(x)\bigr|}_{T_1\ \text{(Monte Carlo)}}
    \;+\;
    \underbrace{\bigl|\mathcal{L}_\phi(x) - \mathcal{L}(x)\bigr|}_{T_2\ \text{(distillation)}}, \end{equation}
and we bound $T_1, T_2$ separately.

Summing, the bounded-difference constant for an $\eta_i$-change is
$c_\eta = \tfrac{4K_{\max}}{n}$. By the symmetric argument,
$c_{\tilde y} = \tfrac{4K_{\max}}{m}$.  Hence
$\sum_{i=1}^{n} c_\eta^2 + \sum_{j=1}^{m} c_{\tilde y}^2
 = 16\,K_{\max}^2\,(1/n + 1/m)$,
and McDiarmid's inequality~\citep{mcdiarmid1989method} gives, for any $t \ge 0$,
\[
  \mathbb{P}\!\bigl(|T_1| \ge t\bigr)
    \;\le\;
    2\exp\!\left(-\tfrac{t^2}{8K_{\max}^2\,(1/n + 1/m)}\right);
\]
equivalently, with probability at least $1 - \delta$,
\begin{equation}
  |T_1| \;\le\;
    K_{\max}\sqrt{8\,\log(2/\delta)\,(1/n + 1/m)}
    \;\le\;
    2\sqrt{2}\,K_{\max}\!\left(\sqrt{\tfrac{\log(2/\delta)}{n}}
                              + \sqrt{\tfrac{\log(2/\delta)}{m}}\right), \end{equation}
where the second inequality uses $\sqrt{a+b}\le\sqrt{a}+\sqrt{b}$.

\emph{Step 2: Distillation term.}
For a distribution $\mathcal{Q}$ on $\mathcal{Y}$ write
$\mu_\mathcal{Q} := \mathbb{E}_{Y\sim\mathcal{Q}}[\varphi_k(Y)]
   \in \mathcal{H}_k$ for its kernel mean embedding. For any
positive-definite kernel $k$ and any two
distributions $\mathcal{Q}_1, \mathcal{Q}_2$,
$\operatorname{MMD}(\mathcal{Q}_1, \mathcal{Q}_2)
  = \|\mu_{\mathcal{Q}_1} - \mu_{\mathcal{Q}_2}\|_{\mathcal{H}_k}$,\footnote{This RKHS-norm identity does not require characteristicness; the characteristic clause of Assumption~\ref{ass:kernel} is used only for the identifiability part of Corollary~\ref{cor:lowrank}.}
and $\|\mu_\mathcal{Q}\|_{\mathcal{H}_k} \le \sqrt{K_{\max}}$ for any
$\mathcal{Q}$. The reverse triangle inequality then gives
\begin{equation}
 \bigl|\operatorname{MMD}(\mathcal{P}_\phi, \mathcal{G})
    - \operatorname{MMD}(\mathcal{P}, \mathcal{G})\bigr|
   \;\le\;
   \|\mu_{\mathcal{P}_\phi} - \mu_{\mathcal{P}}\|_{\mathcal{H}_k}. \end{equation}

Combining~\eqref{eq:loss-mc}, \eqref{eq:loss-dist}
and~\eqref{eq:loss-triangle} gives the stated bound with probability
at least $1 - \delta$.

conclusions:
there exist constants $C_g, C_s, C_v$
depending only on $K_{\max}, L_k, H_k, C_f$ such that
\[
\begin{aligned}
\bigl\|\mathbb{E}\bigl[\nabla_x \widehat{\mathcal{L}}_\phi(x)\bigr] - \nabla_x \mathcal{L}(x)\bigr\|
&\;\le\;
C_g\,\varepsilon_g \;+\; C_s\,\varepsilon_s, \\[6pt]
\mathbb{E}\,\bigl\|\nabla_x \widehat{\mathcal{L}}_\phi(x) - \mathbb{E}[\nabla_x \widehat{\mathcal{L}}_\phi(x)]\bigr\|^2
&\;\le\;
C_v\!\left(\frac{1}{n_{\mathrm{cond}}} + \frac{1}{n_{\mathrm{target}}}\right).
\end{aligned}
\]

