\nabla_x u
 = \mathbb{E}_\eta\Bigl[
    \underbrace{d\varphi_k(f_\phi)\bigl(\partial_x f_\phi - \partial_x f_{\mathrm{true}}\bigr)}_{\Delta_1(\eta)}
   + \underbrace{\bigl(d\varphi_k(f_\phi) - d\varphi_k(f_{\mathrm{true}})\bigr)\,\partial_x f_{\mathrm{true}}}_{\Delta_2(\eta)}
  \Bigr].

\mathbb{E}_\eta\|\Delta_1(\eta)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\bigl(\mathbb{E}_\eta\|\partial_x f_\phi - \partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; L_k\,\varepsilon_g.

\mathbb{E}_\eta\|\Delta_2(\eta)\|_{\mathcal{H}_k}
 \;\le\; H_k\,\bigl(\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|^2\bigr)^{1/2}
   \cdot \bigl(\mathbb{E}_\eta\|\partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; H_k\,C_f\,\varepsilon_s.

\paragraph{Step 2: Bias decomposition.}
By~\eqref{eq:grad-interchange}, the bias equals a deterministic
population gap,
$\|\mathbb{E}[\nabla_x \widehat{\mathcal{L}}_\phi] - \nabla_x \mathcal{L}\|_2
  = \|\nabla_x \mathcal{L}_\phi - \nabla_x \mathcal{L}\|_2$.
By the kernel-mean-embedding identity for MMD$^2$ (using the notation
$A,B,C,u,v$ defined above),
$\mathcal{L}(x) = \|v(x)\|_{\mathcal{H}_k}^2$ and
$\mathcal{L}_\phi(x) = \|u(x)+v(x)\|_{\mathcal{H}_k}^2$.
Differentiating $\psi\mapsto\|\psi\|_{\mathcal{H}_k}^2$ in $\mathcal{H}_k$ gives
$\nabla\|\psi\|^2 = 2\langle \psi, \nabla \psi\rangle_{\mathcal{H}_k}$, hence
\begin{align}
\nabla_x \mathcal{L}_\phi - \nabla_x \mathcal{L}
&= 2\langle u + v, \nabla_x(u+v)\rangle_{\mathcal{H}_k}
   - 2\langle v, \nabla_x v\rangle_{\mathcal{H}_k}\notag\\
&= 2\langle u, \nabla_x u\rangle_{\mathcal{H}_k}
   + 2\langle u, \nabla_x v\rangle_{\mathcal{H}_k}
   + 2\langle v, \nabla_x u\rangle_{\mathcal{H}_k}. \end{align}
Steps~3--4 bound each of the four norms on the right-hand side and
combine them via Cauchy--Schwarz.

\paragraph{Step 3: Bound the four norms.}
We bound each of $\|u\|, \|\nabla_x u\|, \|v\|, \|\nabla_x v\|$ in turn.

\paragraph{(a) $\|u(x)\|_{\mathcal{H}_k} \le L_k\,\varepsilon_s$.}
By Assumption~\ref{ass:repar}, $A(x) = \mathbb{E}_\eta[\varphi_k(f_{\mathrm{true}}(x,\eta))]$
and $B(x) = \mathbb{E}_\eta[\varphi_k(f_\phi(x,\eta))]$ for the same
$\pi$-distributed $\eta$. Hence
\[
u(x) = B(x) - A(x) = \mathbb{E}_\eta\!\bigl[\varphi_k(f_\phi(x,\eta))-\varphi_k(f_{\mathrm{true}}(x,\eta))\bigr].
\]
Jensen's inequality in $\mathcal{H}_k$ gives
$\|u\|_{\mathcal{H}_k} \le \mathbb{E}_\eta\|\varphi_k(f_\phi)-\varphi_k(f_{\mathrm{true}})\|_{\mathcal{H}_k}$,
and $\varphi_k$ being $L_k$-Lipschitz (Assumption~\ref{ass:kernel}(ii))
gives $\|\varphi_k(f_\phi)-\varphi_k(f_{\mathrm{true}})\|_{\mathcal{H}_k} \le L_k\|f_\phi-f_{\mathrm{true}}\|$,
so $\|u\|_{\mathcal{H}_k} \le L_k\,\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|$.
By Cauchy--Schwarz, $\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|
\le (\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|^2)^{1/2}$, and by
Assumption~\ref{ass:samples} the latter is at most $\varepsilon_s$.
Combining,
\[
\|u\|_{\mathcal{H}_k} \;\le\; L_k\,\varepsilon_s.
\]

\paragraph{(b) $\|\nabla_x u(x)\|_{\mathcal{H}_k} \le L_k\,\varepsilon_g + H_k C_f\,\varepsilon_s$.}
We bound $\|\nabla_x u\|$ by adding and subtracting
$d\varphi_k(f_\phi)\,\partial_x f_{\mathrm{true}}$ and applying the
Lipschitz-derivative constant $H_k$ from Assumption~\ref{ass:kernel}(iii).
By Step~1b's Leibniz justification applied to $u$,
\[
\nabla_x u(x)
 = \mathbb{E}_\eta\!\bigl[\,
   \underbrace{d\varphi_k(f_\phi(x,\eta))\,\partial_x f_\phi(x,\eta)}_{\text{linear map }\mathbb{R}^{\dim\mathcal{X}}\to\mathcal{H}_k}
   - d\varphi_k(f_{\mathrm{true}}(x,\eta))\,\partial_x f_{\mathrm{true}}(x,\eta)\bigr].
\]
Add and subtract $d\varphi_k(f_\phi)\,\partial_x f_{\mathrm{true}}$
inside the expectation:
\begin{equation}
\nabla_x u
 = \mathbb{E}_\eta\Bigl[
    \underbrace{d\varphi_k(f_\phi)\bigl(\partial_x f_\phi - \partial_x f_{\mathrm{true}}\bigr)}_{\Delta_1(\eta)}
   + \underbrace{\bigl(d\varphi_k(f_\phi) - d\varphi_k(f_{\mathrm{true}})\bigr)\,\partial_x f_{\mathrm{true}}}_{\Delta_2(\eta)}
  \Bigr]. \end{equation}
By Jensen's inequality and the triangle inequality,
$\|\nabla_x u\|_{\mathcal{H}_k}
\le \mathbb{E}_\eta\|\Delta_1(\eta)\|_{\mathcal{H}_k}
   + \mathbb{E}_\eta\|\Delta_2(\eta)\|_{\mathcal{H}_k}$.

\paragraph{Bound on $\Delta_1$.}
For any linear map $M: \mathbb{R}^{\dim\mathcal{Y}}\to\mathcal{H}_k$
and matrix $J\in\mathbb{R}^{\dim\mathcal{Y}\times\dim\mathcal{X}}$,
the Hilbert--Schmidt operator norm satisfies
$\|M\,J\|_{\mathcal{H}_k} \le \|M\|_{\mathrm{op}}\,\|J\|_F$.
Applying this with $M = d\varphi_k(f_\phi)$ (operator norm $\le L_k$ by
Assumption~\ref{ass:kernel}(ii)) and
$J = \partial_x f_\phi - \partial_x f_{\mathrm{true}}$,
\[
\|\Delta_1(\eta)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\|\partial_x f_\phi(x,\eta) - \partial_x f_{\mathrm{true}}(x,\eta)\|_F.
\]
Taking $\mathbb{E}_\eta$ and applying Cauchy--Schwarz with
Assumption~\ref{ass:grad},
\begin{equation}
\mathbb{E}_\eta\|\Delta_1(\eta)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\bigl(\mathbb{E}_\eta\|\partial_x f_\phi - \partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; L_k\,\varepsilon_g. \end{equation}

\paragraph{Bound on $\Delta_2$.}
Apply the same Hilbert--Schmidt inequality with
$M = d\varphi_k(f_\phi) - d\varphi_k(f_{\mathrm{true}})$ and
$J = \partial_x f_{\mathrm{true}}$:
\[
\|\Delta_2(\eta)\|_{\mathcal{H}_k}
 \;\le\; \|d\varphi_k(f_\phi(x,\eta)) - d\varphi_k(f_{\mathrm{true}}(x,\eta))\|_{\mathrm{op}}
   \cdot \|\partial_x f_{\mathrm{true}}(x,\eta)\|_F.
\]
By Assumption~\ref{ass:kernel}(iii), $d\varphi_k$ is $H_k$-Lipschitz, so
$\|d\varphi_k(f_\phi) - d\varphi_k(f_{\mathrm{true}})\|_{\mathrm{op}}
 \le H_k\,\|f_\phi(x,\eta) - f_{\mathrm{true}}(x,\eta)\|$, giving
\[
\|\Delta_2(\eta)\|_{\mathcal{H}_k}
 \;\le\; H_k\,\|f_\phi-f_{\mathrm{true}}\|\cdot\|\partial_x f_{\mathrm{true}}\|_F.
\]
Take $\mathbb{E}_\eta$ and apply Cauchy--Schwarz in $L^2(\pi)$ to the
product, then use Assumption~\ref{ass:samples} (coupled output
fidelity) and Assumption~\ref{ass:repar}
($\mathbb{E}_\eta\|\partial_x f_{\mathrm{true}}\|_F^2 \le C_f^2$):
\begin{equation}
\mathbb{E}_\eta\|\Delta_2(\eta)\|_{\mathcal{H}_k}
 \;\le\; H_k\,\bigl(\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|^2\bigr)^{1/2}
   \cdot \bigl(\mathbb{E}_\eta\|\partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; H_k\,C_f\,\varepsilon_s. \end{equation}
Combining \eqref{eq:T1-bound}--\eqref{eq:T2-bound},
\begin{equation}
\|\nabla_x u(x)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\varepsilon_g \;+\; H_k\,C_f\,\varepsilon_s. \end{equation}

\paragraph{(c) $\|v(x)\|_{\mathcal{H}_k} \le 2\sqrt{K_{\max}}$.}
For any probability measure $\mathcal{Q}$ on $\mathcal{Y}$,
$\|\mu_\mathcal{Q}\|_{\mathcal{H}_k}^2
 = \mathbb{E}_{Y,Y'\sim\mathcal{Q}}[k(Y,Y')] \le K_{\max}$
by Assumption~\ref{ass:kernel}(i), so
$\|\mu_\mathcal{Q}\|_{\mathcal{H}_k} \le \sqrt{K_{\max}}$.
Triangle inequality gives
$\|v\|_{\mathcal{H}_k} = \|A - C\|_{\mathcal{H}_k}
 \le \|A\|_{\mathcal{H}_k}+\|C\|_{\mathcal{H}_k} \le 2\sqrt{K_{\max}}$.

\paragraph{(d) $\|\nabla_x v(x)\|_{\mathcal{H}_k} \le L_k\,C_f$.}
Repeat the chain-rule expansion of (b) for $A$ alone, with only the
$f_{\mathrm{true}}$ term. By the same Hilbert--Schmidt inequality
($\|d\varphi_k(f_{\mathrm{true}})\,\partial_x f_{\mathrm{true}}\|_{\mathcal{H}_k}
 \le L_k\,\|\partial_x f_{\mathrm{true}}\|_F$) and Cauchy--Schwarz with
Assumption~\ref{ass:repar}'s second-moment bound,
\[
\|\nabla_x v\|_{\mathcal{H}_k}
 = \|\nabla_x A\|_{\mathcal{H}_k}
 \le L_k\,(\mathbb{E}_\eta\|\partial_x f_{\mathrm{true}}\|_F^2)^{1/2}
 \le L_k\,C_f.
\]
($\nabla_x C = 0$ since $\mathcal{G}$ does not depend on $x$.)

\paragraph{(b) $\|\nabla_x u(x)\|_{\mathcal{H}_k} \le L_k\,\varepsilon_g + H_k C_f\,\varepsilon_s$.}
We bound $\|\nabla_x u\|$ by adding and subtracting
$d\varphi_k(f_\phi)\,\partial_x f_{\mathrm{true}}$ and applying the
Lipschitz-derivative constant $H_k$ from Assumption~\ref{ass:kernel}(iii).
By Step~1b's Leibniz justification applied to $u$,
\[
\nabla_x u(x)
 = \mathbb{E}_\eta\!\bigl[\,
   \underbrace{d\varphi_k(f_\phi(x,\eta))\,\partial_x f_\phi(x,\eta)}_{\text{linear map }\mathbb{R}^{\dim\mathcal{X}}\to\mathcal{H}_k}
   - d\varphi_k(f_{\mathrm{true}}(x,\eta))\,\partial_x f_{\mathrm{true}}(x,\eta)\bigr].
\]
Add and subtract $d\varphi_k(f_\phi)\,\partial_x f_{\mathrm{true}}$
inside the expectation:
\begin{equation}
\nabla_x u
 = \mathbb{E}_\eta\Bigl[
    \underbrace{d\varphi_k(f_\phi)\bigl(\partial_x f_\phi - \partial_x f_{\mathrm{true}}\bigr)}_{\Delta_1(\eta)}
   + \underbrace{\bigl(d\varphi_k(f_\phi) - d\varphi_k(f_{\mathrm{true}})\bigr)\,\partial_x f_{\mathrm{true}}}_{\Delta_2(\eta)}
  \Bigr]. \end{equation}
By Jensen's inequality and the triangle inequality,
$\|\nabla_x u\|_{\mathcal{H}_k}
\le \mathbb{E}_\eta\|\Delta_1(\eta)\|_{\mathcal{H}_k}
   + \mathbb{E}_\eta\|\Delta_2(\eta)\|_{\mathcal{H}_k}$.

\paragraph{Bound on $\Delta_1$.}
For any linear map $M: \mathbb{R}^{\dim\mathcal{Y}}\to\mathcal{H}_k$
and matrix $J\in\mathbb{R}^{\dim\mathcal{Y}\times\dim\mathcal{X}}$,
the Hilbert--Schmidt operator norm satisfies
$\|M\,J\|_{\mathcal{H}_k} \le \|M\|_{\mathrm{op}}\,\|J\|_F$.
Applying this with $M = d\varphi_k(f_\phi)$ (operator norm $\le L_k$ by
Assumption~\ref{ass:kernel}(ii)) and
$J = \partial_x f_\phi - \partial_x f_{\mathrm{true}}$,
\[
\|\Delta_1(\eta)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\|\partial_x f_\phi(x,\eta) - \partial_x f_{\mathrm{true}}(x,\eta)\|_F.
\]
Taking $\mathbb{E}_\eta$ and applying Cauchy--Schwarz with
Assumption~\ref{ass:grad},
\begin{equation}
\mathbb{E}_\eta\|\Delta_1(\eta)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\bigl(\mathbb{E}_\eta\|\partial_x f_\phi - \partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; L_k\,\varepsilon_g. \end{equation}

\paragraph{Bound on $\Delta_2$.}
