 \;\le\; H_k\,\bigl(\mathbb{E}_\eta\|f_\phi-f_{\mathrm{true}}\|^2\bigr)^{1/2}
   \cdot \bigl(\mathbb{E}_\eta\|\partial_x f_{\mathrm{true}}\|_F^2\bigr)^{1/2}
 \;\le\; H_k\,C_f\,\varepsilon_s. \end{equation}
Combining \eqref{eq:T1-bound}--\eqref{eq:T2-bound},
\begin{equation}
\|\nabla_x u(x)\|_{\mathcal{H}_k}
 \;\le\; L_k\,\varepsilon_g \;+\; H_k\,C_f\,\varepsilon_s. \end{equation}

